def begin(number,topic,goal):
    r=Report(number,topic);r.heading(topic);r.heading('Цель и задание',2)
    r.paragraph(goal)
    r.paragraph('Рассматривается информационная система формирования и актуализации карточек компьютерных систем ООО «Юкомс». Она связывает версии состава, предложения поставщиков, расчётные показатели, изображения и ревизии товарных карточек.')
    return r

def source(r,n):
    r.sources([f'Проектирование предметно-ориентированных информационных систем. Практическая работа №{n}. Методическое задание РТУ МИРЭА, предоставленное к работе.'])

def diagram(r,title,file,landscape=True,height=13.5):
    r.page(landscape,new_page=True)
    r.figure(title,SCHEMES/(file+'.png'),max_height=height)

def finish(r,n):
    r.page(False);source(r,n);return r.save()

