def study_note():
    # Personal explanation is deliberately separate from the submission report.
    r=Report(8,'Разбор формул к защите',filename='ПР8_Разбор_формул.docx')
    r.heading('Разбор формул к защите практической работы 8')
    r.paragraph('Этот материал предназначен для подготовки к устной защите. В отчёте для сдачи остаются формулы, обозначения и алгоритмы; подробное чтение и контрольная подстановка собраны здесь.')
    r.heading('Как читать обозначения')
    r.table('Обозначения',['Запись','Как читать и что означает'],[
      ('qᵢ, pᵢ, wᵢ','«Количество, цена и масса в позиции и». Нижний индекс i отличает позиции; это не умножение на i.'),('∑ от i = 1 до n','«Сумма по всем позициям от первой до последней». Для каждой позиции умножить количество на цену или массу, затем сложить.'),('C(1 + m)','«Себестоимость, умноженная на один плюс доля наценки». При m = 0,20 множитель равен 1,20.'),('(C(1 + m) + L) / (1 − c)','Сначала начислить наценку, добавить логистику, затем разделить на долю выручки, остающуюся после комиссии.'),('⌈P₀ / d⌉','«Округлить P нулевое, делённое на шаг, вверх до целого». Угловые скобки — математический потолок.'),('i ∈ K','«И принадлежит множеству К»: суммировать только компоненты, потребляющие питание.'),('HБП ≥ (1 + β) ∑qᵢHᵢ','«Мощность блока питания не меньше мощности потребителей с запасом». При β = 0,30 запас равен 30 %.')],[4.2,12.3])
    r.heading('Почему комиссия находится в знаменателе')
    r.paragraph('Площадка удерживает c от продажной цены P₀. Продавцу остаётся P₀(1 − c). Эта сумма должна покрыть C(1 + m) + L. Из равенства P₀(1 − c) = C(1 + m) + L получается деление на 1 − c. Прибавление 15 % к себестоимости не компенсирует комиссию 15 % от выручки.')
    r.heading('Контрольная подстановка')
    r.paragraph('Стоимость компонентов: 16 000 + 12 000 + 2 × 4 000 + 5 000 + 4 500 + 5 500 = 51 000 руб. Сборка A = 2 000 руб., упаковка B = 500 руб.; C = 53 500 руб.')
    r.paragraph('При m = 0,20, c = 0,15 и L = 700 руб. получаем P₀ = (53 500 × 1,20 + 700) / 0,85 = 76 352,941176… руб. Шаг d = 100 руб.: P₀ / d = 763,5294…; потолок равен 764; P = 764 × 100 = 76 400 руб.')
    r.paragraph('Масса компонентов — 7,020 кг. При массе упаковки b = 0,800 кг итог W = 7,820 кг. Потребление: 65 + 40 + 2 × 5 + 8 = 123 Вт. С запасом: 123 × 1,30 = 159,9 Вт. Блок 650 Вт проходит эту проверку.')
    r.heading('Что убрано из отчёта и почему')
    r.paragraph('Отдельный контрольный расчёт методичкой не предписан. Он полезен для проверки и защиты, поэтому сохранён здесь. В отчёте определены все переменные и индексы при первом появлении, как требует задание. Формальные множества предложений, lexmin и многострочная формула повторной публикации заменены понятным описанием подбора и профильными расчётами цены и массы.')
    for child in list(r.document.element.body)[:16]:r.document.element.body.remove(child)
    r.document.core_properties.title='Разбор формул практической работы 8 для защиты'
    output=Path(os.environ.get('PPOIS_REPORT_OUTPUT',str(SUBJECT/'Материалы_для_защиты')));return r.save(output)

